diff --git a/libarchive/archive_read_support_format_ar.c b/libarchive/archive_read_support_format_ar.c
index 8873101..783936e 100644
--- a/libarchive/archive_read_support_format_ar.c
+++ b/libarchive/archive_read_support_format_ar.c
@@ -291,24 +291,30 @@ _ar_read_header(struct archive_read *a, struct archive_entry *entry,
 			return (ARCHIVE_FATAL);
 		}

-		/* Read the filename table into memory. */
-		st = malloc(strtab_size);
+		/*
+		 * Reserve one extra byte: ar_parse_gnu_filename_table()
+		 * inspects the byte immediately after the declared table
+		 * data to confirm it is a valid pad character, so give it
+		 * somewhere safe to land instead of reading whatever the
+		 * last real data byte happens to be.
+		 */
+		st = malloc(strtab_size + 1);
 		if (st == NULL) {
 			archive_set_error(&a->archive, ENOMEM,
 			    "Can't allocate filename table buffer");
 			return (ARCHIVE_FATAL);
 		}
 		ar->strtab = st;
-		ar->strtab_size = strtab_size;
+		ar->strtab_size = strtab_size + 1;

 		if (*unconsumed) {
 			__archive_read_consume(a, *unconsumed);
 			*unconsumed = 0;
 		}

-		if ((b = __archive_read_ahead(a, strtab_size, NULL)) == NULL)
+		if ((b = __archive_read_ahead(a, strtab_size + 1, NULL)) == NULL)
 			return (ARCHIVE_FATAL);
-		memcpy(st, b, strtab_size);
+		memcpy(st, b, strtab_size + 1);

 		/* Skip special file entry. */
 		if (archive_read_format_ar_skip(a) != ARCHIVE_OK)

